draft_contract.raw:
version: '5.0'
model_name: draft_commerce_vault
hubs:
  - hub_customer: { business_key: customer_tax_id }
  - hub_order:    { business_key: order_id }

final_contract.raw:
version: '5.0'
model_name: global_commerce_vault
hubs:
  - hub_customer: { business_key: customer_tax_id }
  - hub_order:    { business_key: order_id }
links:
  - lnk_order_customer: { source: erp_orders }
satellites:
  - sat_customer_core: { split: CORE }
  - sat_customer_pii:  { split: RESTRICTED_PII }

final_sql.raw:
-- 4-Zone DuckDB Data Vault 2.0 DDL
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE SCHEMA IF NOT EXISTS staging;
CREATE SCHEMA IF NOT EXISTS raw_vault;
CREATE SCHEMA IF NOT EXISTS business_vault;

CREATE TABLE raw_vault.hub_customer (
    hk_customer VARCHAR(64) PRIMARY KEY,
    customer_tax_id VARCHAR(64) NOT NULL,
    load_dts TIMESTAMP WITH TIME ZONE NOT NULL,
    rec_src VARCHAR(64) NOT NULL
);

harness.raw:
version: '1.0'
